SELECT 
FROM iot_device_schedule

    schedule_id = #{scheduleId}
    AND device_id = #{deviceId}
    AND status = 'ACTIVE' AND next_fire_at <= #{dueAt}
    AND FALSE


    ORDER BY next_fire_at, schedule_id
    ORDER BY schedule_id DESC

OFFSET #{offset} LIMIT #{limit}

mapper.update:
UPDATE iot_device_schedule
status = #{status.value}, next_fire_at = #{nextFireAt.value}, next_fire_at = NULL, last_planned_at = #{plannedAt.value}, last_triggered_at = #{triggeredAt.value}, last_execution_status = #{executionStatus.value}, last_message_id = #{messageId.value}, last_message_id = NULL, last_failure_code = #{failureCode.value}, last_failure_code = NULL, version = version + 1
WHERE schedule_id = #{scheduleId} AND version = #{expectedVersion} AND status <> 'CANCELLED' AND status = #{expectedStatus}
